package vn.covie.admin.application;
import static org.assertj.core.api.Assertions.assertThat; import static org.assertj.core.api.Assertions.assertThatThrownBy; import org.junit.jupiter.api.Test; import vn.covie.shared.web.ApiException; import vn.covie.shared.web.ErrorCode;
class AdminPageRequestValidatorTest { private final AdminPageRequestValidator validator=new AdminPageRequestValidator(); @Test void acceptsOnlyWhitelistedSortsAndSafeBounds(){assertThat(validator.validate(0,50,null).sort()).isEqualTo("CREATED_DESC");assertThatThrownBy(()->validator.validate(0,101,"CREATED_DESC")).isInstanceOf(ApiException.class).extracting(e->((ApiException)e).code()).isEqualTo(ErrorCode.VALIDATION_FAILED);assertThatThrownBy(()->validator.validate(0,10,"id desc")).isInstanceOf(ApiException.class).extracting(e->((ApiException)e).code()).isEqualTo(ErrorCode.VALIDATION_FAILED);}}
